             if g[r][c] not in (bg, 2)]
    if not cells:
        return g

    top, bottom = min(r for r, c in cells), max(r for r, c in cells)
    left, right = min(c for r, c in cells), max(c for r, c in cells)
    obj = [(r - top, c, g[r][c]) for r, c in cells]
    height = bottom - top + 1

    if bottom < barrier:
        new_top = barrier - height
        mark = new_top - 1
    elif top > barrier:
        new_top = barrier + 1
        mark = new_top + height
    else:
